<?php require_once __DIR__.'/../includes/bootstrap.php';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf(); $name=trim($_POST['full_name']??'');$username=trim($_POST['username']??'');$email=strtolower(trim($_POST['email']??''));$pw=$_POST['password']??'';$confirm=$_POST['confirm_password']??'';
$err='Please check your details and try again.'; if(strlen($name)<2||strlen($name)>120||!preg_match('/^[A-Za-z0-9_]{3,32}$/',$username)||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($email)>254||!password_valid($pw)||!hash_equals($pw,$confirm)){flash('error',$err);}else{try{$q=db()->prepare('SELECT id FROM users WHERE username=? OR email=?');$q->execute([$username,$email]);if($q->fetch()){flash('error','That username or email is already in use.');}else{$q=db()->prepare('INSERT INTO users(full_name,username,email,password_hash) VALUES(?,?,?,?)');$q->execute([$name,$username,$email,password_digest($pw)]);$id=(int)db()->lastInsertId();$secret=totp()->generateSecretKey(32);$_SESSION['setup_2fa']=['id'=>$id,'secret'=>$secret];redirect('/setup-2fa.php');}}catch(Throwable $e){error_log((string)$e);flash('error','Registration could not be completed. Check server configuration and try again.');}}}
render_start('Create your account'); ?><p class="lede">Set up your account, then link an authenticator app before signing in.</p><form method="post" data-validate><?=csrf_field()?><label>Full name<input name="full_name" autocomplete="name" minlength="2" maxlength="120" required></label><label>Username<input name="username" autocomplete="username" pattern="[A-Za-z0-9_]{3,32}" required><small>3–32 letters, numbers, or underscores.</small></label><label>Email<input type="email" name="email" autocomplete="email" maxlength="254" required></label><label>Password<span class="pw"><input type="password" name="password" autocomplete="new-password" minlength="12" required><button type="button" class="toggle">Show</button></span><small>At least 12 characters with upper and lower case, a number, and a symbol.</small></label><label>Confirm password<input type="password" name="confirm_password" autocomplete="new-password" required></label><button class="button" type="submit">Create account</button></form><p class="below">Already registered? <a href="/login.php">Sign in</a></p><?php render_end();
